@ConfigGroup(BankStonksConfig.GROUP)
public interface BankStonksConfig extends Config
{
	String GROUP = "bankstonks";
	String KEY_BLOCK_LIST = "blockList";

	@ConfigSection(
		name = "Display",
		description = "How the sidebar list is shown.",
		position = 0
	)
	String SECTION_DISPLAY = "display";

	@ConfigSection(
		name = "Bank overlay",
		description = "Profit/loss drawn on your bank slots.",
		position = 1
	)
	String SECTION_OVERLAY = "overlay";

	@ConfigSection(
		name = "Colours",
		description = "Colours for gains and losses.",
		position = 2
	)
	String SECTION_COLOURS = "colours";

	@ConfigSection(
		name = "Block list",
		description = "Items to hide from the list.",
		position = 3
	)
	String SECTION_BLOCK_LIST = "blockListSection";

	@ConfigItem(
		keyName = "showPercent",
		name = "Show profit %",
		description = "Show the profit/loss as a percentage of the amount invested.",
		section = SECTION_DISPLAY,
		position = 1
	)
	default boolean showPercent()
	{
		return true;
	}

	@ConfigItem(
		keyName = "sortOrder",
		name = "Sort by",
		description = "How to order the items in the panel.",
		section = SECTION_DISPLAY,
		position = 2
	)
	default SortOrder sortOrder()
	{
		return SortOrder.BIGGEST_MOVERS;
	}

	@ConfigItem(
		keyName = "applyGeTax",
		name = "Subtract GE tax",
		description = "Value holdings at what you would net after the 2% GE sell tax (capped at 5M per item) instead of the raw wiki price.",
		section = SECTION_DISPLAY,
		position = 3
	)
	default boolean applyGeTax()
	{
		return false;
	}

	@ConfigItem(
		keyName = "bankOverlay",
		name = "Show bank overlay",
		description = "Draw each tracked item's profit/loss directly on its slot in the bank.",
		section = SECTION_OVERLAY,
		position = 1
	)
	default boolean bankOverlay()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "profitColor",
		name = "Profit colour",
		description = "Colour used for a gain.",
		section = SECTION_COLOURS,
		position = 1
	)
	default Color profitColor()
	{
		return new Color(76, 175, 80);
	}

	@Alpha
	@ConfigItem(
		keyName = "lossColor",
		name = "Loss colour",
		description = "Colour used for a loss.",
		section = SECTION_COLOURS,
		position = 2
	)
	default Color lossColor()
	{
		return new Color(244, 67, 54);
	}

	@ConfigItem(
		keyName = KEY_BLOCK_LIST,
		name = "Block list",
		description = "Comma-separated item names that are never shown in the list (they are still tracked in the background). A name with no * must match exactly; a name with a * matches any item containing that text, e.g. '*potion*' blocks all potions and 'prayer potion*' blocks all doses.",
		section = SECTION_BLOCK_LIST,
		position = 1
	)
	default String blockList()
	{
		return "";
	}
}

package com.bankstonks;

/**
 * Shared number/age formatting used by the panel and overlays.
 */
public final class Format
{
	private Format()
	{
	}

	/** Signed compact gp, e.g. "+1.23M", "-450.0K", "+999". */
	public static String gp(long value)
	{
		long abs = Math.abs(value);
		String sign = value > 0 ? "+" : (value < 0 ? "-" : "");
		if (abs >= 1_000_000_000L)
		{
			return sign + String.format("%.2fB", abs / 1_000_000_000.0);
		}
		if (abs >= 1_000_000L)
		{
			return sign + String.format("%.2fM", abs / 1_000_000.0);
		}
		if (abs >= 1_000L)
		{
			return sign + String.format("%.1fK", abs / 1_000.0);
		}
		return sign + abs;
	}

	/** Exact gp with thousands separators, e.g. "1,234,567". */
	public static String exact(long value)
	{
		return String.format("%,d", value);
	}

	/** Unsigned compact gp, e.g. "1.23M", "450.0K", "999". */
	public static String plain(long value)
	{
		if (value >= 1_000_000L)
		{
			return String.format("%.2fM", value / 1_000_000.0);
		}
		if (value >= 1_000L)
		{
			return String.format("%.1fK", value / 1_000.0);
		}
		return Long.toString(value);
	}

	/** Bare "held since" age, e.g. "today", "12d", "5mo", "2y 3mo"; empty if unknown. */
	public static String age(long firstBoughtEpochMs)
	{
		if (firstBoughtEpochMs <= 0)
		{
			return "";
		}
		long days = (System.currentTimeMillis() - firstBoughtEpochMs) / 86_400_000L;
		if (days <= 0)
		{
			return "today";
		}
		if (days < 30)
		{
			return days + "d";
		}
		long months = days / 30;
		if (months < 12)
		{
			return months + "mo";
		}
		long years = months / 12;
		long remMonths = months % 12;
		return remMonths > 0 ? years + "y " + remMonths + "mo" : years + "y";
	}
}

package com.bankstonks.model;

import java.util.HashMap;
import java.util.Map;
import lombok.Data;

/**
 * The full persisted state for one account. Serialized to the RuneLite config as JSON.
 *
 * <p>The block list is not stored here — it lives in the plugin config (global, editable in
 * settings) as item names.</p>
 */
@Data
public class PortfolioData
{
	/** Cost-basis records keyed by item id. */
	private Map<Integer, TrackedItem> items = new HashMap<>();

	/** Last-seen bank quantity keyed by item id. */
	private Map<Integer, Integer> bank = new HashMap<>();

	/** Last-seen GE offer state keyed by slot index (0-7). */
	private Map<Integer, SlotState> slots = new HashMap<>();

	/** Monotonic counter for assigning lot ids to GE offers. */
	private long nextLotId;

	/** Guards against null maps after deserializing older/partial JSON. */
	public void ensureInitialized()
	{
		if (items == null)
		{
			items = new HashMap<>();
		}
		for (TrackedItem item : items.values())
		{
			if (item != null)
			{
				item.ensureInitialized();
			}
		}
		if (bank == null)
		{
			bank = new HashMap<>();
		}
		if (slots == null)
		{
			slots = new HashMap<>();
		}
	}
}

package com.bankstonks.model;

import java.util.List;
import lombok.Value;

/**
 * A single computed row shown in the panel. Immutable snapshot for the UI thread.
 */
@Value
public class PortfolioRow
{
	int itemId;
	String name;

	/** min(totalBought, current bank quantity) — the amount we value. */
	int quantity;

	/** Average price paid for the valued units (most-recent lots). */
	long averageBuyPrice;

	/** Current wiki (GE) price. */
	long currentPrice;

	/** Profit/loss per single item: currentPrice - averageBuyPrice. */
	long profitEach;

	/** Total profit/loss: profitEach * quantity. */
	long profitTotal;

	/** Epoch millis of the first recorded buy ("held since"); 0 if unknown. */
	long firstBoughtEpochMs;

	/** The individual buy lots (newest first), for the expandable history. */
	List<Lot> lots;

	/** Whether this item is locked (pinned to one buy, shown without a history dropdown). */
	boolean locked;

	/** Profit as a percentage of the amount invested, or 0 if nothing invested. */
	public double profitPercent()
	{
		long invested = averageBuyPrice * quantity;
		return invested <= 0 ? 0 : (profitTotal * 100.0) / invested;
	}
}

package com.bankstonks.model;

import lombok.Value;

/**
 * The result of valuing a held quantity against a {@link TrackedItem}'s lots: the average
 * price paid for those units and the most recent buy date among them ("held since").
 */
@Value
public class LotValuation
{
	long averagePrice;
	long heldSinceEpochMs;
}

package com.bankstonks.model;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * The persisted cost-basis record for a single item id: the list of buy lots (GE fills and
 * manual entries).
 *
 * <p>The current holding is always valued at the <b>most recent</b> purchases (LIFO): to value
 * {@code n} held units we walk the lots newest-first and take {@code n} units, ignoring older
 * lots beyond that. This means selling then rebuying shows the latest buy price (not a blended
 * average), and items that leave and come back (bank/inventory/death/storage) keep their data
 * because lots are never deleted.</p>
 */
@Data
@NoArgsConstructor
public class TrackedItem
{
	/** Keep this many lots individually; older ones are merged so storage stays bounded. */
	private static final int MAX_LOTS = 40;

	private List<Lot> lots = new ArrayList<>();

	/**
	 * A pinned buy. When set, the item is "locked": it is shown regardless of what you currently
	 * hold and valued at this lot's price/date/quantity instead of the live LIFO holding. It is a
	 * snapshot copy, so it survives lots being merged or removed. Null means unlocked.
	 */
	private Lot lockedLot;

	public void ensureInitialized()
	{
		if (lots == null)
		{
			lots = new ArrayList<>();
		}
	}

	public boolean isLocked()
	{
		return lockedLot != null;
	}

	/** Locks the item to its most recent buy. No-op if there are no lots. */
	public void lockToNewest()
	{
		Lot newest = null;
		for (Lot lot : lots)
		{
			if (newest == null || lot.getEpochMs() > newest.getEpochMs())
			{
				newest = lot;
			}
		}
		if (newest != null)
		{
			lockedLot = copy(newest);
		}
	}

	/** Locks the item to a specific buy (matched by quantity, spent and date). */
	public void lockToLot(int quantity, long spent, long epochMs)
	{
		for (Lot lot : lots)
		{
			if (lot.getQuantity() == quantity && lot.getSpent() == spent && lot.getEpochMs() == epochMs)
			{
				lockedLot = copy(lot);
				return;
			}
		}
	}

	public void unlock()
	{
		lockedLot = null;
	}

	private static Lot copy(Lot lot)
	{
		return new Lot(lot.getQuantity(), lot.getSpent(), lot.getEpochMs(), lot.getOfferId());
	}

	/** Records a standalone buy (e.g. a manual entry) as a new lot. */
	public void addBuy(int quantity, long spent, long epochMs)
	{
		if (quantity <= 0 || spent <= 0)
		{
			return;
		}
		lots.add(new Lot(quantity, spent, epochMs, 0));
		compact();
	}

	/**
	 * Adds a GE fill to the lot for {@code offerId}, so partial fills of one offer accumulate
	 * into a single lot (showing the offer's overall average price). Creates the lot on the
	 * first fill.
	 */
	public void addOfferFill(long offerId, int quantity, long spent, long epochMs)
	{
		if (quantity <= 0 || spent <= 0)
		{
			return;
		}
		if (offerId != 0)
		{
			for (Lot lot : lots)
			{
				if (lot.getOfferId() == offerId)
				{
					lot.setQuantity(lot.getQuantity() + quantity);
					lot.setSpent(lot.getSpent() + spent);
					return;
				}
			}
		}
		lots.add(new Lot(quantity, spent, epochMs, offerId));
		compact();
	}

	/** Total quantity ever bought (sum of all lots). */
	public int totalBought()
	{
		int total = 0;
		for (Lot lot : lots)
		{
			total += lot.getQuantity();
		}
		return total;
	}

	/**
	 * Values the most recent {@code quantity} held units (LIFO): walks lots newest-first,
	 * taking units until {@code quantity} is covered. Returns the average price of those units
	 * and the most recent buy date among them (the "held since").
	 */
	public LotValuation value(int quantity)
	{
		if (quantity <= 0 || lots.isEmpty())
		{
			return new LotValuation(0, 0);
		}
		List<Lot> newestFirst = new ArrayList<>(lots);
		newestFirst.sort(Comparator.comparingLong(Lot::getEpochMs).reversed());

		long cost = 0;
		int taken = 0;
		long lastBuyEpochMs = 0;
		for (Lot lot : newestFirst)
		{
			if (taken >= quantity)
			{
				break;
			}
			if (lastBuyEpochMs == 0)
			{
				// "Held since" is the most recent buy that makes up the current holding.
				lastBuyEpochMs = lot.getEpochMs();
			}
			int take = Math.min(quantity - taken, lot.getQuantity());
			cost += lot.unitPrice() * take;
			taken += take;
		}
		long average = taken > 0 ? cost / taken : 0;
		return new LotValuation(average, lastBuyEpochMs);
	}

	/** Merges the oldest lots together until at most {@link #MAX_LOTS} remain. */
	private void compact()
	{
		if (lots.size() <= MAX_LOTS)
		{
			return;
		}
		lots.sort(Comparator.comparingLong(Lot::getEpochMs));
		while (lots.size() > MAX_LOTS)
		{
			Lot a = lots.remove(0);
			Lot b = lots.remove(0);
			// Merged history loses its offer identity (0) so it is never appended to again.
			lots.add(0, new Lot(a.getQuantity() + b.getQuantity(), a.getSpent() + b.getSpent(),
				Math.min(a.getEpochMs(), b.getEpochMs()), 0));
		}
	}
}

package com.bankstonks.model;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * The last-seen state of a single Grand Exchange slot, persisted per account.
 *
 * <p>Kept so that we can compute the delta between successive {@code GrandExchangeOfferChanged}
 * events (a single buy fills in increments) and, crucially, so we do not double-count offers
 * that the client re-broadcasts on login.</p>
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class SlotState
{
	private int itemId;
	private int quantitySold;
	private long spent;

	/** The lot id this offer accumulates into, so its partial fills group into one lot. */
	private long lotId;
}

package com.bankstonks.model;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * A single recorded purchase: a quantity bought for a total price at a point in time.
 * Lots are never mutated after creation; valuation walks them newest-first (LIFO).
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class Lot
{
	private int quantity;
	private long spent;
	private long epochMs;

	/** The GE offer this lot came from, so partial fills of one offer accumulate into it. 0 for manual entries. */
	private long offerId;

	public long unitPrice()
	{
		return quantity <= 0 ? 0 : spent / quantity;
	}
}

