/**
 * Sidebar panel: manual-add form, search filter, total P/L header, the held-item list and a
 * collapsible block list.
 */
public class BankStonksPanel extends PluginPanel
{
	private final ItemManager itemManager;
	private final BankStonksConfig config;
	private final PortfolioActions actions;

	private final JLabel totalLabel = new JLabel("0", SwingConstants.CENTER);

	private final JTextField nameField = new JTextField();
	private final JTextField qtyField = new JTextField();
	private final JTextField priceField = new JTextField();
	private final JTextField heldSinceField = new JTextField();
	private final JLabel statusLabel = new JLabel(" ", SwingConstants.CENTER);

	private final JButton addToggle = new JButton();
	private final JPanel addBody = new JPanel();
	private JPanel addFormPanel;
	private boolean addExpanded = false;

	private final IconTextField searchField = new IconTextField();

	private final JPanel listPanel = new JPanel();
	private final JLabel emptyLabel = new JLabel("<html><center>No tracked items yet.<br>Buy on the GE or add one above.</center></html>", SwingConstants.CENTER);

	private List<PortfolioRow> allRows = new ArrayList<>();

	/** Item ids whose buy-history dropdown is expanded. */
	private final Set<Integer> expandedItems = new HashSet<>();

	private static final DateTimeFormatter LOT_DATE = DateTimeFormatter.ofPattern("d MMM yy", Locale.ENGLISH);

	/** Accent colour marking a locked (pinned) item or buy. */
	private static final Color LOCK_COLOR = new Color(230, 185, 60);

	/** Small gold padlock shown next to a locked item's held line. */
	private static final ImageIcon LOCK_ICON = buildLockIcon();

	private static ImageIcon buildLockIcon()
	{
		int w = 7;
		int lock = 9;
		// JLabel centres the icon on the font's line box, which sits below the small font's visible
		// glyphs, so transparent space below the padlock lifts it up onto the text's centre.
		int bottomPad = 4;
		int h = lock + bottomPad;
		BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setColor(LOCK_COLOR);
		g.setStroke(new BasicStroke(1.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.draw(new Arc2D.Double(1.6, 1.0, w - 3.2, 5.5, 0, 180, Arc2D.OPEN));
		g.fill(new RoundRectangle2D.Double(0.5, 3.5, w - 1.0, lock - 3.5, 1.8, 1.8));
		// Punch a keyhole so it reads as a lock.
		g.setComposite(AlphaComposite.Clear);
		g.fill(new Ellipse2D.Double(w / 2.0 - 0.8, 4.9, 1.6, 1.6));
		g.setComposite(AlphaComposite.SrcOver);
		g.dispose();
		return new ImageIcon(img);
	}

	public BankStonksPanel(ItemManager itemManager, BankStonksConfig config, PortfolioActions actions)
	{
		this.itemManager = itemManager;
		this.config = config;
		this.actions = actions;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		addStretched(buildHeader());
		add(Box.createVerticalStrut(8));
		addStretched(buildAddForm());
		add(Box.createVerticalStrut(8));
		addStretched(buildSearchField());
		add(Box.createVerticalStrut(8));

		listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
		listPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		listPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(listPanel);

		emptyLabel.setForeground(Color.GRAY);
		emptyLabel.setFont(FontManager.getRunescapeSmallFont());
	}

	// ---- construction helpers ------------------------------------------------

	/** Adds a component to the vertical layout stretched to the full panel width. */
	private void addStretched(JComponent c)
	{
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		add(c);
	}

	private JPanel buildHeader()
	{
		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		JLabel title = new JLabel("Bank Stonks profit / loss", SwingConstants.CENTER);
		title.setFont(FontManager.getRunescapeSmallFont());
		title.setForeground(Color.LIGHT_GRAY);

		totalLabel.setFont(FontManager.getRunescapeBoldFont());
		totalLabel.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));

		header.add(title, BorderLayout.NORTH);
		header.add(totalLabel, BorderLayout.CENTER);
		return header;
	}

	private JPanel buildAddForm()
	{
		JPanel form = new JPanel();
		form.setLayout(new BoxLayout(form, BoxLayout.Y_AXIS));
		form.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		form.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		addFormPanel = form;

		addToggle.setFocusPainted(false);
		addToggle.setHorizontalAlignment(SwingConstants.LEFT);
		addToggle.setFont(FontManager.getRunescapeSmallFont());
		addToggle.setForeground(Color.LIGHT_GRAY);
		addToggle.setContentAreaFilled(false);
		addToggle.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));
		addToggle.setText(addExpanded ? "[-] Add item manually" : "[+] Add item manually");
		addToggle.addActionListener(e -> toggleAddForm());

		styleField(nameField);
		styleField(qtyField);
		styleField(priceField);
		styleField(heldSinceField);

		nameField.setToolTipText("Item name");
		JPanel nameLabeled = labeled("Item", nameField);

		JPanel qtyPrice = new JPanel(new GridLayout(1, 2, 4, 0));
		qtyPrice.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		qtyField.setToolTipText("Quantity");
		priceField.setToolTipText("Price each (e.g. 1.5m, 250k, 1200)");
		qtyPrice.add(labeled("Qty", qtyField));
		qtyPrice.add(labeled("Price ea", priceField));

		heldSinceField.setToolTipText("Optional. When you bought it, e.g. 2023-03-15, Jan 2024, or 2y / 6mo ago. Blank = now.");
		JPanel heldSince = labeled("Held since (optional)", heldSinceField);

		JButton addBtn = new JButton("Add");
		addBtn.setFocusPainted(false);
		addBtn.addActionListener(e -> onAdd());

		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		statusLabel.setForeground(Color.GRAY);

		addBody.setLayout(new BoxLayout(addBody, BoxLayout.Y_AXIS));
		addBody.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		addBody.setVisible(addExpanded);

		stretch(addToggle);
		stretch(nameLabeled);
		stretch(qtyPrice);
		stretch(heldSince);
		stretch(addBtn);
		stretch(statusLabel);

		addBody.add(Box.createVerticalStrut(6));
		addBody.add(nameLabeled);
		addBody.add(Box.createVerticalStrut(4));
		addBody.add(qtyPrice);
		addBody.add(Box.createVerticalStrut(4));
		addBody.add(heldSince);
		addBody.add(Box.createVerticalStrut(4));
		addBody.add(addBtn);
		addBody.add(statusLabel);
		addBody.setAlignmentX(Component.LEFT_ALIGNMENT);
		addBody.setMaximumSize(new Dimension(Integer.MAX_VALUE, addBody.getPreferredSize().height));

		form.add(addToggle);
		form.add(addBody);
		return form;
	}

	private void styleField(JTextField field)
	{
		field.setBackground(ColorScheme.DARK_GRAY_COLOR);
		field.setForeground(Color.WHITE);
		field.setCaretColor(Color.WHITE);
		field.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(2, 4, 2, 4)));
	}

	private void toggleAddForm()
	{
		addExpanded = !addExpanded;
		addBody.setVisible(addExpanded);
		addToggle.setText(addExpanded ? "[-] Add item manually" : "[+] Add item manually");
		addFormPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, addFormPanel.getPreferredSize().height));
		revalidate();
		repaint();
	}

	private static void stretch(JComponent c)
	{
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
	}

	private JPanel labeled(String text, Component field)
	{
		JPanel p = new JPanel(new BorderLayout(0, 2));
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(Color.GRAY);
		p.add(l, BorderLayout.NORTH);
		p.add(field, BorderLayout.CENTER);
		return p;
	}

	private IconTextField buildSearchField()
	{
		searchField.setIcon(IconTextField.Icon.SEARCH);
		searchField.setPreferredSize(new Dimension(100, 30));
		searchField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchField.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		searchField.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				renderList();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				renderList();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				renderList();
			}
		});
		searchField.addClearListener(this::renderList);
		return searchField;
	}

	// ---- actions -------------------------------------------------------------

	private void onAdd()
	{
		String name = nameField.getText().trim();
		Integer qty = parseAmountInt(qtyField.getText());
		Long price = parseAmount(priceField.getText());

		if (name.isEmpty() || qty == null || qty <= 0 || price == null || price <= 0)
		{
			setStatus("Enter an item, quantity and price.", config.lossColor());
			return;
		}

		Long heldSince = parseHeldSince(heldSinceField.getText());
		if (heldSince == null)
		{
			setStatus("Couldn't read 'held since'. Try 2023-03-15 or 2y.", config.lossColor());
			return;
		}

		// Fields are cleared only on success, via clearManualEntry() from the plugin.
		actions.addManual(name, qty, price, heldSince);
	}

	/** Shows a transient status message under the add form. Thread-safe. */
	public void setStatus(String message, Color color)
	{
		SwingUtilities.invokeLater(() ->
		{
			statusLabel.setText(message == null || message.isEmpty() ? " " : message);
			statusLabel.setForeground(color);
		});
	}

	/** Clears the manual-add fields. Called only after a successful add. Thread-safe. */
	public void clearManualEntry()
	{
		SwingUtilities.invokeLater(() ->
		{
			nameField.setText("");
			qtyField.setText("");
			priceField.setText("");
			heldSinceField.setText("");
		});
	}

	// ---- rendering -----------------------------------------------------------

	/** Rebuilds the panel from the given rows. Thread-safe. */
	public void update(List<PortfolioRow> rows, long total)
	{
		SwingUtilities.invokeLater(() ->
		{
			allRows = rows;

			totalLabel.setText(Format.gp(total));
			totalLabel.setForeground(colorFor(total));

			renderList();
		});
	}

	private void renderList()
	{
		listPanel.removeAll();

		String filter = searchField.getText() == null ? "" : searchField.getText().trim().toLowerCase(Locale.ROOT);
		List<PortfolioRow> visible = new ArrayList<>();
		for (PortfolioRow row : allRows)
		{
			if (filter.isEmpty() || row.getName().toLowerCase(Locale.ROOT).contains(filter))
			{
				visible.add(row);
			}
		}

		if (allRows.isEmpty())
		{
			listPanel.add(emptyLabel);
		}
		else if (visible.isEmpty())
		{
			JLabel none = new JLabel("No matches.", SwingConstants.CENTER);
			none.setForeground(Color.GRAY);
			none.setFont(FontManager.getRunescapeSmallFont());
			listPanel.add(none);
		}
		else
		{
			for (PortfolioRow row : visible)
			{
				listPanel.add(buildRow(row));
				listPanel.add(Box.createVerticalStrut(4));
			}
		}

		listPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, listPanel.getPreferredSize().height));
		listPanel.revalidate();
		listPanel.repaint();
	}

	private JPanel buildRow(PortfolioRow row)
	{
		boolean collapsible = row.getLots() != null && row.getLots().size() > 1;
		boolean expanded = collapsible && expandedItems.contains(row.getItemId());

		JPanel container = new JPanel();
		container.setLayout(new BoxLayout(container, BoxLayout.Y_AXIS));
		container.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		container.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel main = new JPanel(new BorderLayout(6, 0));
		main.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		main.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 4));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(32, 32));
		AsyncBufferedImage image = itemManager.getImage(row.getItemId(), row.getQuantity(), row.getQuantity() > 1);
		image.addTo(icon);
		main.add(icon, BorderLayout.WEST);

		String age = Format.age(row.getFirstBoughtEpochMs());
		String heldText = age.isEmpty() ? "" : "held " + age;
		JPanel middle = new JPanel(new GridLayout(heldText.isEmpty() ? 2 : 3, 1));
		middle.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		JLabel name = new JLabel(row.getName());
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(Color.WHITE);
		if (row.isLocked())
		{
			// A small gold padlock in front of the name marks the item as locked.
			name.setIcon(LOCK_ICON);
			name.setIconTextGap(4);
			name.setVerticalAlignment(SwingConstants.CENTER);
			name.setVerticalTextPosition(SwingConstants.CENTER);
			name.setToolTipText("Locked to this buy");
		}
		JLabel detail = new JLabel(row.getQuantity() + " @ " + Format.plain(row.getAverageBuyPrice()));
		detail.setFont(FontManager.getRunescapeSmallFont());
		detail.setForeground(Color.GRAY);
		detail.setToolTipText(Format.exact(row.getAverageBuyPrice()) + " gp each");
		// Wrap so the price tooltip only covers the text, not the whole row width.
		JPanel detailWrap = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		detailWrap.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		detailWrap.add(detail);
		middle.add(name);
		middle.add(detailWrap);
		if (!heldText.isEmpty())
		{
			JLabel held = new JLabel(heldText);
			held.setFont(FontManager.getRunescapeSmallFont());
			held.setForeground(Color.GRAY.darker());
			middle.add(held);
		}
		main.add(middle, BorderLayout.CENTER);

		JPanel plInfo = new JPanel(new GridLayout(config.showPercent() ? 2 : 1, 1));
		plInfo.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		String currentTip = Format.exact(row.getCurrentPrice()) + " gp each";
		JLabel pl = new JLabel(Format.gp(row.getProfitTotal()), SwingConstants.RIGHT);
		pl.setFont(FontManager.getRunescapeSmallFont());
		pl.setForeground(colorFor(row.getProfitTotal()));
		pl.setToolTipText(currentTip);
		plInfo.add(pl);
		if (config.showPercent())
		{
			JLabel pct = new JLabel(String.format("%+.1f%%", row.profitPercent()), SwingConstants.RIGHT);
			pct.setFont(FontManager.getRunescapeSmallFont());
			pct.setForeground(colorFor(row.getProfitTotal()));
			pct.setToolTipText(currentTip);
			plInfo.add(pct);
		}
		main.add(plInfo, BorderLayout.EAST);

		// Right-click the item to untrack (delete all its history; reappears if rebought) or
		// block (never show; still tracked in the background).
		JPopupMenu popup = new JPopupMenu();
		if (row.isLocked())
		{
			JMenuItem unlock = new JMenuItem("Unlock " + row.getName());
			unlock.setToolTipText("Stop pinning this item to a single buy");
			unlock.addActionListener(e -> actions.unlockItem(row.getItemId()));
			popup.add(unlock);
		}
		else
		{
			JMenuItem lock = new JMenuItem("Lock " + row.getName());
			lock.setToolTipText("Pin this item to its most recent buy; stays shown even when you hold none");
			lock.addActionListener(e -> actions.lockItem(row.getItemId()));
			popup.add(lock);
		}
		JMenuItem untrack = new JMenuItem("Untrack " + row.getName());
		untrack.setToolTipText("Remove all history for this item; reappears if bought again");
		untrack.addActionListener(e -> actions.untrackItem(row.getItemId()));
		JMenuItem block = new JMenuItem("Block " + row.getName());
		block.setToolTipText("Never show; still tracked in the background. Undo in settings.");
		block.addActionListener(e -> actions.blockItem(row.getName()));
		popup.add(untrack);
		popup.add(block);
		main.setComponentPopupMenu(popup);
		inheritPopup(main);

		// The whole row is clickable when there is buy history to expand: hover highlights it and
		// a left click toggles the history dropdown.
		if (collapsible)
		{
			main.setToolTipText(row.getLots().size() + " buys, click to " + (expanded ? "hide" : "show") + " history");
			MouseAdapter rowMouse = new MouseAdapter()
			{
				@Override
				public void mouseEntered(MouseEvent e)
				{
					setRowBackground(main, ColorScheme.DARKER_GRAY_HOVER_COLOR);
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					if (main.getMousePosition() == null)
					{
						setRowBackground(main, ColorScheme.DARKER_GRAY_COLOR);
					}
				}

				@Override
				public void mousePressed(MouseEvent e)
				{
					if (SwingUtilities.isLeftMouseButton(e))
					{
						toggleExpanded(row.getItemId());
					}
				}
			};
			addMouseListenerDeep(main, rowMouse, Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		}

		stretch(main);
		container.add(main);

		if (expanded)
		{
			for (Lot lot : row.getLots())
			{
				container.add(buildLotRow(row.getItemId(), lot));
			}
		}

		container.setMaximumSize(new Dimension(Integer.MAX_VALUE, container.getPreferredSize().height));
		return container;
	}

	/** A single buy in the expanded history: quantity, unit price and date, right-click to lock/remove. */
	private JPanel buildLotRow(int itemId, Lot lot)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		// A left accent marks it as a nested history entry; the inset lines it up under the name.
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(6, 23, 6, 6)));

		JLabel info = new JLabel(lot.getQuantity() + " @ " + Format.plain(lot.unitPrice()));
		info.setFont(FontManager.getRunescapeSmallFont());
		info.setForeground(Color.LIGHT_GRAY);
		info.setToolTipText(Format.exact(lot.unitPrice()) + " gp each");
		row.add(info, BorderLayout.WEST);

		JLabel date = new JLabel(formatDate(lot.getEpochMs()), SwingConstants.RIGHT);
		date.setFont(FontManager.getRunescapeSmallFont());
		date.setForeground(Color.GRAY);
		row.add(date, BorderLayout.EAST);

		// Locking a specific buy pins the item to it; the item then collapses to that single buy.
		JPopupMenu popup = new JPopupMenu();
		JMenuItem lock = new JMenuItem("Lock this buy");
		lock.addActionListener(e -> actions.lockLot(itemId, lot.getQuantity(), lot.getSpent(), lot.getEpochMs()));
		popup.add(lock);
		JMenuItem untrack = new JMenuItem("Remove this buy");
		untrack.addActionListener(e -> actions.untrackLot(itemId, lot.getQuantity(), lot.getSpent(), lot.getEpochMs()));
		popup.add(untrack);
		row.setComponentPopupMenu(popup);
		inheritPopup(row);

		// Hover highlight signals the row is interactive (right-click to remove).
		MouseAdapter hover = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				setRowBackground(row, ColorScheme.DARK_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (row.getMousePosition() == null)
				{
					setRowBackground(row, ColorScheme.DARK_GRAY_COLOR);
				}
			}
		};
		addMouseListenerDeep(row, hover, null);

		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	private void toggleExpanded(int itemId)
	{
		if (!expandedItems.remove(itemId))
		{
			expandedItems.add(itemId);
		}
		renderList();
	}

	static String formatDate(long epochMs)
	{
		if (epochMs <= 0)
		{
			return "";
		}
		return Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()).toLocalDate().format(LOT_DATE);
	}

	/** Recolors a row: sets the panel's background and that of any nested panels (labels are transparent). */
	private static void setRowBackground(java.awt.Container row, Color color)
	{
		row.setBackground(color);
		for (java.awt.Component child : row.getComponents())
		{
			if (child instanceof JPanel)
			{
				setRowBackground((java.awt.Container) child, color);
			}
		}
	}

	/**
	 * Attaches a mouse listener to a row and every descendant so hover/click work anywhere on it,
	 * and optionally applies a cursor to the whole row.
	 */
	private static void addMouseListenerDeep(java.awt.Component c, MouseAdapter adapter, Cursor cursor)
	{
		c.addMouseListener(adapter);
		if (cursor != null)
		{
			c.setCursor(cursor);
		}
		if (c instanceof java.awt.Container)
		{
			for (java.awt.Component child : ((java.awt.Container) c).getComponents())
			{
				addMouseListenerDeep(child, adapter, cursor);
			}
		}
	}

	/** Lets a row's child components trigger the row's right-click menu too. */
	private static void inheritPopup(java.awt.Container container)
	{
		for (java.awt.Component child : container.getComponents())
		{
			if (child instanceof JComponent)
			{
				((JComponent) child).setInheritsPopupMenu(true);
			}
			if (child instanceof java.awt.Container)
			{
				inheritPopup((java.awt.Container) child);
			}
		}
	}

	private Color colorFor(long value)
	{
		if (value > 0)
		{
			return config.profitColor();
		}
		if (value < 0)
		{
			return config.lossColor();
		}
		return Color.LIGHT_GRAY;
	}

	/** Parses "1.5m", "250k", "1,200", "999" into a long. Returns null if unparseable. */
	static Long parseAmount(String raw)
	{
		if (raw == null)
		{
			return null;
		}
		String s = raw.trim().toLowerCase(Locale.ROOT).replace(",", "").replace(" ", "");
		if (s.isEmpty())
		{
			return null;
		}
		double mult = 1;
		char last = s.charAt(s.length() - 1);
		if (last == 'k')
		{
			mult = 1_000;
			s = s.substring(0, s.length() - 1);
		}
		else if (last == 'm')
		{
			mult = 1_000_000;
			s = s.substring(0, s.length() - 1);
		}
		else if (last == 'b')
		{
			mult = 1_000_000_000;
			s = s.substring(0, s.length() - 1);
		}
		try
		{
			return (long) (Double.parseDouble(s) * mult);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	static Integer parseAmountInt(String raw)
	{
		Long v = parseAmount(raw);
		if (v == null || v > Integer.MAX_VALUE)
		{
			return null;
		}
		return v.intValue();
	}

	private static final Pattern REL_TOKEN =
		Pattern.compile("(\\d+)\\s*(years?|yrs?|y|months?|mons?|mo|weeks?|wks?|w|days?|d)");

	private static final String[] DATE_FORMATS =
		{"yyyy-MM-dd", "yyyy/MM/dd", "d-M-yyyy", "d/M/yyyy", "d MMM yyyy", "d MMMM yyyy"};

	private static final String[] YEAR_MONTH_FORMATS =
		{"yyyy-MM", "MMM yyyy", "MMMM yyyy", "MMM-yyyy"};

	/**
	 * Parses the optional "held since" input into an epoch-millis timestamp.
	 *
	 * <ul>
	 *   <li>blank → 0 (meaning "use now")</li>
	 *   <li>relative age: "2y", "6mo", "2y 3mo", "30d ago"</li>
	 *   <li>absolute date: "2023-03-15", "Jan 2024", "2022"</li>
	 * </ul>
	 *
	 * @return epoch millis, 0 for blank, or {@code null} if the value can't be understood.
	 */
	static Long parseHeldSince(String raw)
	{
		if (raw == null)
		{
			return 0L;
		}
		String s = raw.trim().toLowerCase(Locale.ROOT);
		if (s.isEmpty())
		{
			return 0L;
		}
		Long relative = parseRelativeAge(s);
		if (relative != null)
		{
			return relative;
		}
		return parseAbsoluteDate(s);
	}

	private static Long parseRelativeAge(String s)
	{
		String cleaned = s.replace("ago", "").replace(",", " ").trim();
		if (cleaned.isEmpty())
		{
			return null;
		}
		Matcher m = REL_TOKEN.matcher(cleaned);
		long totalDays = 0;
		int idx = 0;
		boolean any = false;
		while (m.find())
		{
			if (!cleaned.substring(idx, m.start()).trim().isEmpty())
			{
				return null;
			}
			totalDays += Long.parseLong(m.group(1)) * unitDays(m.group(2));
			idx = m.end();
			any = true;
		}
		if (!any || !cleaned.substring(idx).trim().isEmpty())
		{
			return null;
		}
		return System.currentTimeMillis() - totalDays * 86_400_000L;
	}

	private static long unitDays(String unit)
	{
		if (unit.startsWith("y"))
		{
			return 365;
		}
		if (unit.startsWith("mo"))
		{
			return 30;
		}
		if (unit.startsWith("w"))
		{
			return 7;
		}
		return 1;
	}

	private static Long parseAbsoluteDate(String s)
	{
		for (String fmt : DATE_FORMATS)
		{
			try
			{
				return toEpochMs(LocalDate.parse(s, caseInsensitive(fmt)));
			}
			catch (Exception ignored)
			{
				// try next format
			}
		}
		for (String fmt : YEAR_MONTH_FORMATS)
		{
			try
			{
				return toEpochMs(YearMonth.parse(s, caseInsensitive(fmt)).atDay(1));
			}
			catch (Exception ignored)
			{
				// try next format
			}
		}
		if (s.matches("\\d{4}"))
		{
			return toEpochMs(LocalDate.of(Integer.parseInt(s), 1, 1));
		}
		return null;
	}

	private static DateTimeFormatter caseInsensitive(String pattern)
	{
		return new DateTimeFormatterBuilder().parseCaseInsensitive().appendPattern(pattern).toFormatter(Locale.ENGLISH);
	}

	private static long toEpochMs(LocalDate date)
	{
		return date.atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli();
	}
}

package com.bankstonks.ui;

/**
 * Callbacks the panel uses to ask the plugin to mutate portfolio state. The plugin performs
 * the work on the client thread and refreshes the panel afterwards.
 */
public interface PortfolioActions
{
	/**
	 * Manually records a buy for the item best matching {@code query}.
	 *
	 * @param query             item name to resolve (fuzzy)
	 * @param quantity          quantity acquired
	 * @param priceEach         price paid per item
	 * @param heldSinceEpochMs  when it was bought (epoch millis), or 0 to use now
	 */
	void addManual(String query, int quantity, long priceEach, long heldSinceEpochMs);

	/**
	 * Deletes an item's tracked data. It disappears from the list and reappears (fresh) only
	 * if bought again. This is not the block list — it is a one-time removal.
	 */
	void untrackItem(int itemId);

	/** Removes a single buy lot from an item's history (matched by quantity, spent and date). */
	void untrackLot(int itemId, int quantity, long spent, long epochMs);

	/**
	 * Adds an item to the block list so it is never shown (it is still tracked in the
	 * background). Reversible only by editing the block list in settings.
	 */
	void blockItem(String itemName);

	/** Locks an item to its most recent buy: pinned in the list and valued at that buy. */
	void lockItem(int itemId);

	/** Locks an item to a specific buy (matched by quantity, spent and date). */
	void lockLot(int itemId, int quantity, long spent, long epochMs);

	/** Removes an item's lock. */
	void unlockItem(int itemId);
}

package com.bankstonks;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Helpers for the comma-separated item-name list stored in config (the "Block list").
 *
 * <p>Matching is case-insensitive. An entry may contain {@code *} as a wildcard matching any
 * run of characters, so {@code prayer potion*} matches every dose ("Prayer potion(1)"…), and
 * {@code *(unf)} matches every unfinished potion.</p>
 *
 * <p>Patterns are compiled once and cached per CSV value, since {@link #matches} is called
 * frequently (per item, and per bank item each render frame).</p>
 */
final class BlockLists
{
	private static volatile String cachedCsv;
	private static volatile List<Pattern> cachedPatterns = Collections.emptyList();

	private BlockLists()
	{
	}

	/** Splits a CSV config value into trimmed, non-empty entries (original case preserved). */
	static List<String> names(String csv)
	{
		List<String> out = new ArrayList<>();
		if (csv == null)
		{
			return out;
		}
		for (String part : csv.split(","))
		{
			String trimmed = part.trim();
			if (!trimmed.isEmpty())
			{
				out.add(trimmed);
			}
		}
		return out;
	}

	/** Whether the item name matches any entry in the list (supporting {@code *} wildcards). */
	static boolean matches(String csv, String itemName)
	{
		if (itemName == null)
		{
			return false;
		}
		List<Pattern> patterns = compiled(csv);
		if (patterns.isEmpty())
		{
			return false;
		}
		String lower = itemName.toLowerCase(Locale.ROOT);
		for (Pattern pattern : patterns)
		{
			if (pattern.matcher(lower).find())
			{
				return true;
			}
		}
		return false;
	}

	private static List<Pattern> compiled(String csv)
	{
		String key = csv == null ? "" : csv;
		if (key.equals(cachedCsv))
		{
			return cachedPatterns;
		}
		List<Pattern> patterns = new ArrayList<>();
		for (String entry : names(csv))
		{
			patterns.add(toPattern(entry.toLowerCase(Locale.ROOT)));
		}
		cachedPatterns = patterns;
		cachedCsv = key;
		return patterns;
	}

	private static Pattern toPattern(String entry)
	{
		// Entries with a wildcard match as "contains" (unanchored), so "* potion" also
		// matches "Divine super combat potion(4)". Entries without a wildcard are anchored,
		// so they only match the exact item name.
		boolean wildcard = entry.indexOf('*') >= 0;
		StringBuilder regex = new StringBuilder();
		if (!wildcard)
		{
			regex.append('^');
		}
		String[] parts = entry.split("\\*", -1);
		for (int i = 0; i < parts.length; i++)
		{
			if (i > 0)
			{
				regex.append(".*");
			}
			if (!parts[i].isEmpty())
			{
				regex.append(Pattern.quote(parts[i]));
			}
		}
		if (!wildcard)
		{
			regex.append('$');
		}
		return Pattern.compile(regex.toString());
	}

	/** Returns the CSV with {@code name} appended, or unchanged if already present. */
	static String add(String csv, String name)
	{
		List<String> names = names(csv);
		for (String existing : names)
		{
			if (existing.equalsIgnoreCase(name))
			{
				return csv == null ? "" : csv;
			}
		}
		names.add(name);
		return String.join(", ", names);
	}

	/** Returns the CSV with {@code name} removed (exact, case-insensitive). */
	static String remove(String csv, String name)
	{
		List<String> names = names(csv);
		names.removeIf(n -> n.equalsIgnoreCase(name));
		return String.join(", ", names);
	}
}

package com.bankstonks;

import com.bankstonks.model.SlotState;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.GrandExchangeOfferChanged;

/**
 * Watches Grand Exchange offers and records the cost basis of every <b>buy</b> that fills.
 *
 * <p>A single buy is reported incrementally across many {@code GrandExchangeOfferChanged}
 * events. We diff each event against the last-seen state of that slot to extract only the
 * newly-filled quantity/spend. Because the previous state is persisted, offers that the
 * client re-broadcasts on login produce a zero delta and are not double-counted.</p>
 *
 * <p>{@code offer.getSpent() / offer.getQuantitySold()} gives the true average price paid,
 * including partial fills at different prices, so we accumulate spend directly.</p>
 */
@Slf4j
@Singleton
public class GrandExchangeBuyTracker
{
	private final PortfolioManager manager;

	/**
	 * True while the client is replaying the batch of existing GE offers that fires on login/hop.
	 * During this window an offer we have no baseline for was bought in a previous session (and
	 * recorded then), so we adopt it as the baseline instead of recording it again.
	 */
	private volatile boolean loginSync;

	@Inject
	public GrandExchangeBuyTracker(PortfolioManager manager)
	{
		this.manager = manager;
	}

	/** Marks the start of the login/hop offer replay (set true), or its end (set false). */
	public void setLoginSync(boolean syncing)
	{
		this.loginSync = syncing;
	}

	/** @return true if a buy was recorded (so the caller can refresh the UI). */
	public boolean handle(GrandExchangeOfferChanged event)
	{
		if (!manager.hasAccount())
		{
			return false;
		}

		final int slot = event.getSlot();
		final GrandExchangeOffer offer = event.getOffer();
		final GrandExchangeOfferState state = offer.getState();

		if (state == GrandExchangeOfferState.EMPTY)
		{
			// On login the client resets every slot to EMPTY before replaying the real offers.
			// Clearing here would drop the baseline (and the offer's lot identity), so a later
			// fill would start a new lot. Skip clearing during the login/hop replay window.
			if (!loginSync)
			{
				manager.clearSlot(slot);
				manager.save();
			}
			return false;
		}

		if (!isBuy(state))
		{
			// Sell offers do not affect cost basis; forget the slot so a later buy in the
			// same slot starts from a clean delta (but not during the login replay, as above).
			if (!loginSync)
			{
				manager.clearSlot(slot);
				manager.save();
			}
			return false;
		}

		final int itemId = offer.getItemId();
		final int quantitySold = offer.getQuantitySold();
		final long spent = offer.getSpent();

		SlotState prev = manager.getSlot(slot);
		boolean continuing = prev != null && prev.getItemId() == itemId && quantitySold >= prev.getQuantitySold();
		int prevQty = continuing ? prev.getQuantitySold() : 0;
		long prevSpent = continuing ? prev.getSpent() : 0;

		int deltaQty = quantitySold - prevQty;
		long deltaSpent = spent - prevSpent;

		// Partial fills of the same offer accumulate into one lot; a new offer gets a fresh id.
		long offerId = continuing ? prev.getLotId() : 0;

		boolean recorded = false;
		if (deltaQty > 0 && deltaSpent > 0)
		{
			if (loginSync && !continuing)
			{
				// Login/hop replay of an offer we have no baseline for: it was bought (and
				// recorded) in a prior session. Adopt it as the baseline without recording, so the
				// same buy is never counted twice. A later real fill diffs against this baseline.
				log.debug("login sync: adopting baseline item={} qty={} spent={} (not recorded)", itemId, quantitySold, spent);
			}
			else
			{
				if (offerId == 0)
				{
					offerId = manager.nextOfferId();
				}
				manager.recordOfferFill(itemId, deltaQty, deltaSpent, System.currentTimeMillis(), offerId);
				recorded = true;
				log.debug("recorded buy fill: item={} qty={} spent={} offer={}", itemId, deltaQty, deltaSpent, offerId);
			}
		}

		manager.setSlot(slot, new SlotState(itemId, quantitySold, spent, offerId));
		manager.save();
		return recorded;
	}

	private static boolean isBuy(GrandExchangeOfferState state)
	{
		return state == GrandExchangeOfferState.BUYING
			|| state == GrandExchangeOfferState.BOUGHT
			|| state == GrandExchangeOfferState.CANCELLED_BUY;
	}
}

package com.bankstonks;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;

/**
 * Snapshots the bank whenever it changes (which only happens while the bank is open) and
 * caches the item quantities so the panel can value holdings even when the bank is closed.
 */
@Slf4j
@Singleton
public class BankTracker
{
	private final PortfolioManager manager;

	@Inject
	public BankTracker(PortfolioManager manager)
	{
		this.manager = manager;
	}

	/** @return true if the bank snapshot was updated. */
	public boolean handle(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.BANK || !manager.hasAccount())
		{
			return false;
		}

		ItemContainer container = event.getItemContainer();
		if (container == null)
		{
			return false;
		}

		Map<Integer, Integer> quantities = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			quantities.merge(item.getId(), item.getQuantity(), Integer::sum);
		}

		manager.updateBank(quantities);
		manager.save();
		return true;
	}
}

package com.bankstonks;

import com.bankstonks.model.Lot;
import com.bankstonks.model.LotValuation;
import com.bankstonks.model.PortfolioData;
import com.bankstonks.model.PortfolioRow;
import com.bankstonks.model.SlotState;
import com.bankstonks.model.TrackedItem;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemMapping;
import net.runelite.client.game.ItemVariationMapping;

/**
 * Owns the portfolio state for the currently logged-in account: cost basis per item,
 * last-seen bank quantities and GE slot states. Handles load/save to the RuneLite config
 * and computes the display rows.
 *
 * <p>All reads/writes happen from either the client thread (GE/bank events, row computation)
 * or the config-manager threads; the underlying maps are only touched from the client thread
 * so no extra synchronization is needed for the MVP.</p>
 */
@Slf4j
@Singleton
public class PortfolioManager
{
	static final String CONFIG_GROUP = "bankstonks";
	static final String DATA_KEY_PREFIX = "data_";

	private final ConfigManager configManager;
	private final Gson gson;

	private long accountHash = -1L;
	private PortfolioData data = new PortfolioData();

	@Inject
	public PortfolioManager(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	/** Switches to the given account, loading its persisted data. No-op if unchanged. */
	public void setAccount(long hash)
	{
		if (hash == accountHash)
		{
			return;
		}
		accountHash = hash;
		load();
	}

	public boolean hasAccount()
	{
		return accountHash != -1L;
	}

	private void load()
	{
		if (accountHash == -1L)
		{
			data = new PortfolioData();
			return;
		}
		String json = configManager.getConfiguration(CONFIG_GROUP, DATA_KEY_PREFIX + accountHash);
		if (json == null || json.isEmpty())
		{
			data = new PortfolioData();
		}
		else
		{
			try
			{
				data = gson.fromJson(json, PortfolioData.class);
				if (data == null)
				{
					data = new PortfolioData();
				}
				data.ensureInitialized();
			}
			catch (Exception e)
			{
				log.warn("failed to parse stored portfolio for account {}, starting fresh", accountHash, e);
				data = new PortfolioData();
			}
		}
	}

	public void save()
	{
		if (accountHash == -1L)
		{
			return;
		}
		configManager.setConfiguration(CONFIG_GROUP, DATA_KEY_PREFIX + accountHash, gson.toJson(data));
	}

	// ---- GE slot bookkeeping -------------------------------------------------

	public SlotState getSlot(int slot)
	{
		return data.getSlots().get(slot);
	}

	public void setSlot(int slot, SlotState state)
	{
		data.getSlots().put(slot, state);
	}

	public void clearSlot(int slot)
	{
		data.getSlots().remove(slot);
	}

	// ---- cost basis ----------------------------------------------------------

	/**
	 * Records a manual buy as a standalone lot.
	 *
	 * @param heldSinceEpochMs the purchase time for this lot; if &le; 0 the current time is used.
	 */
	public void recordBuy(int itemId, int quantity, long spent, long heldSinceEpochMs)
	{
		if (quantity <= 0 || spent <= 0)
		{
			return;
		}
		long epochMs = heldSinceEpochMs > 0 ? heldSinceEpochMs : System.currentTimeMillis();
		data.getItems().computeIfAbsent(itemId, id -> new TrackedItem()).addBuy(quantity, spent, epochMs);
	}

	/** Records a GE fill, grouping the partial fills of one offer into a single lot. */
	public void recordOfferFill(int itemId, int quantity, long spent, long epochMs, long offerId)
	{
		if (quantity <= 0 || spent <= 0)
		{
			return;
		}
		data.getItems().computeIfAbsent(itemId, id -> new TrackedItem()).addOfferFill(offerId, quantity, spent, epochMs);
	}

	/** Returns a fresh lot id for a newly-seen GE offer. */
	public long nextOfferId()
	{
		long id = data.getNextLotId() + 1;
		data.setNextLotId(id);
		return id;
	}

	public TrackedItem getTracked(int itemId)
	{
		return data.getItems().get(itemId);
	}

	/**
	 * Deletes an item's tracked data ("untrack"). It disappears from the list and will only
	 * reappear, freshly, if it is bought again.
	 */
	public void removeItem(int itemId)
	{
		data.getItems().remove(itemId);
	}

	/**
	 * Removes a single buy lot (matched by quantity, spent and date). If it was the last lot,
	 * the whole item is dropped.
	 */
	public void removeLot(int itemId, int quantity, long spent, long epochMs)
	{
		TrackedItem tracked = data.getItems().get(itemId);
		if (tracked == null)
		{
			return;
		}
		List<Lot> lots = tracked.getLots();
		for (int i = 0; i < lots.size(); i++)
		{
			Lot lot = lots.get(i);
			if (lot.getQuantity() == quantity && lot.getSpent() == spent && lot.getEpochMs() == epochMs)
			{
				lots.remove(i);
				break;
			}
		}
		if (lots.isEmpty())
		{
			data.getItems().remove(itemId);
		}
	}

	/** Locks an item to its most recent buy (pinning it, shown regardless of holdings). */
	public void lockItem(int itemId)
	{
		TrackedItem tracked = data.getItems().get(itemId);
		if (tracked != null)
		{
			tracked.lockToNewest();
		}
	}

	/** Locks an item to a specific buy (matched by quantity, spent and date). */
	public void lockLot(int itemId, int quantity, long spent, long epochMs)
	{
		TrackedItem tracked = data.getItems().get(itemId);
		if (tracked != null)
		{
			tracked.lockToLot(quantity, spent, epochMs);
		}
	}

	/** Removes the lock from an item. */
	public void unlockItem(int itemId)
	{
		TrackedItem tracked = data.getItems().get(itemId);
		if (tracked != null)
		{
			tracked.unlock();
		}
	}

	/**
	 * The tradeable "base" item ids a held item counts towards. Uses RuneLite's {@link ItemMapping}
	 * (the same data {@link ItemManager#getItemPrice} sums) so a combination item resolves to the
	 * tradeable parts it was assembled from (e.g. an avernic defender counts as its hilt), then
	 * normalises through {@link ItemVariationMapping} for charged/dose variants.
	 *
	 * <p>Only single-quantity components are followed, so assembled parts (hilts, shards, ornament
	 * kits) count but consumed bulk charges (scales, darts) do not resurrect as "held".</p>
	 */
	/** Adds a held item's quantity to every tradeable base it counts towards. */
	private static void addHeld(Map<Integer, Integer> heldByBase, int itemId, int quantity)
	{
		for (int base : representedBases(itemId))
		{
			heldByBase.merge(base, quantity, Integer::sum);
		}
	}

	/**
	 * Assembled items that RuneLite has no price for and does not model in {@link ItemMapping}
	 * (the finished item is untradeable), mapped to the tradeable component you actually bought.
	 * Lets a held avernic defender count as its hilt, etc. Hand maintained; add entries as needed.
	 */
	private static final Map<Integer, int[]> ASSEMBLED_COMPONENTS = new HashMap<>();

	static
	{
		// Others (amulet of blood fury, ferocious gloves, etc.) are already resolved by ItemMapping.
		ASSEMBLED_COMPONENTS.put(22322, new int[]{22477}); // Avernic defender -> Avernic defender hilt
	}

	private static Set<Integer> representedBases(int itemId)
	{
		Set<Integer> bases = new HashSet<>();
		int[] manual = ASSEMBLED_COMPONENTS.get(itemId);
		if (manual != null)
		{
			for (int component : manual)
			{
				bases.add(ItemVariationMapping.map(component));
			}
			return bases;
		}
		Collection<ItemMapping> mappings = ItemMapping.map(itemId);
		if (mappings != null)
		{
			for (ItemMapping mapping : mappings)
			{
				if (mapping.getQuantity() == 1)
				{
					bases.add(ItemVariationMapping.map(mapping.getTradeableItem()));
				}
			}
		}
		if (bases.isEmpty())
		{
			bases.add(ItemVariationMapping.map(itemId));
		}
		return bases;
	}

	/**
	 * Finds the tracked (bought) item id that corresponds to an item sitting in the bank,
	 * matching across variations and combination items so a charged, banked or assembled item
	 * resolves to the item it was bought as. Returns -1 if nothing tracked corresponds.
	 */
	public int boughtIdForBankItem(int bankItemId)
	{
		if (data.getItems().containsKey(bankItemId))
		{
			return bankItemId;
		}
		Set<Integer> bases = representedBases(bankItemId);
		for (Integer id : data.getItems().keySet())
		{
			if (bases.contains(ItemVariationMapping.map(id)))
			{
				return id;
			}
		}
		return -1;
	}

	/**
	 * Whether an item is on the untracked list and should be excluded. Supports {@code *}
	 * wildcards. Single source of truth used by the panel, buy tracker and bank overlay.
	 */
	public static boolean isBlocked(BankStonksConfig config, String itemName)
	{
		return BlockLists.matches(config.blockList(), itemName);
	}

	// ---- bank ----------------------------------------------------------------

	public void updateBank(Map<Integer, Integer> bankQuantities)
	{
		data.setBank(bankQuantities);
	}

	// ---- display -------------------------------------------------------------

	/** Total profit/loss across all held items from the last {@link #buildRows} call. */
	private volatile long lastTotalProfit;

	public long getLastTotalProfit()
	{
		return lastTotalProfit;
	}

	/**
	 * Net value of one item after the 2% GE sell tax (floored, capped at 5M per item).
	 * Items priced under 50 are tax-exempt. Buys are never taxed, so this only ever adjusts
	 * the current price side of the profit calculation.
	 */
	public static long netAfterTax(long price)
	{
		if (price < 50)
		{
			return price;
		}
		long tax = Math.min((long) Math.floor(price * 0.02), 5_000_000L);
		return price - tax;
	}

	/**
	 * Builds the rows to render. Held quantity is min(totalBought, held) so that items
	 * obtained outside the GE (drops, etc.) are never valued as profit, and sold-off stock
	 * drops out automatically.
	 *
	 * <p>Held counts the bank snapshot plus the live inventory/equipment quantities passed in
	 * (an item is only ever in one container, so there is no double counting).</p>
	 *
	 * <p>Must be called on the client thread (uses {@link ItemManager}).</p>
	 */
	public List<PortfolioRow> buildRows(ItemManager itemManager, BankStonksConfig config, Map<Integer, Integer> liveQuantities)
	{
		// Total held quantity grouped by variation base, so a charged/banked item counts
		// towards the uncharged item it was bought as (and dose variants collapse together).
		// Bank is a cached snapshot; inventory and worn items are live.
		Map<Integer, Integer> heldByBase = new HashMap<>();
		for (Map.Entry<Integer, Integer> e : data.getBank().entrySet())
		{
			addHeld(heldByBase, e.getKey(), e.getValue());
		}
		if (liveQuantities != null)
		{
			for (Map.Entry<Integer, Integer> e : liveQuantities.entrySet())
			{
				addHeld(heldByBase, e.getKey(), e.getValue());
			}
		}

		// Attribute held items to purchases most-recent first, so a newer buy claims the held units
		// before an older one. This resolves the ambiguity when the same items could satisfy either
		// a set purchase or individual-piece purchases: whichever you bought more recently wins
		// (consistent with the LIFO cost basis). A set claims un-unpacked set items plus complete
		// sets assembled from loose pieces, then consumes those pieces so nothing double counts.
		List<Map.Entry<Integer, TrackedItem>> claims = new ArrayList<>();
		for (Map.Entry<Integer, TrackedItem> entry : data.getItems().entrySet())
		{
			if (!entry.getValue().isLocked() && entry.getValue().totalBought() > 0)
			{
				claims.add(entry);
			}
		}
		claims.sort((a, b) ->
		{
			int cmp = Long.compare(newestBuy(b.getValue()), newestBuy(a.getValue()));
			return cmp != 0 ? cmp : Integer.compare(a.getKey(), b.getKey());
		});

		List<PortfolioRow> rows = new ArrayList<>();
		long total = 0;

		// Locked items are pinned to one buy: always shown, valued at that lot's price/date/quantity,
		// and excluded from the held-pool allocation below (their quantity is the locked lot's, not
		// what you currently hold).
		for (Map.Entry<Integer, TrackedItem> entry : data.getItems().entrySet())
		{
			TrackedItem tracked = entry.getValue();
			if (!tracked.isLocked())
			{
				continue;
			}
			int itemId = entry.getKey();
			if (isBlocked(config, itemManager.getItemComposition(itemId).getName()))
			{
				continue;
			}
			PortfolioRow row = buildLockedRow(itemManager, config, itemId, tracked);
			rows.add(row);
			total += row.getProfitTotal();
		}

		for (Map.Entry<Integer, TrackedItem> entry : claims)
		{
			int itemId = entry.getKey();
			TrackedItem tracked = entry.getValue();
			if (isBlocked(config, itemManager.getItemComposition(itemId).getName()))
			{
				continue;
			}

			int quantity;
			int[] pieces = ItemSets.piecesFor(itemId);
			if (pieces != null)
			{
				int unopened = heldByBase.getOrDefault(ItemVariationMapping.map(itemId), 0);
				int completeSets = Integer.MAX_VALUE;
				for (int piece : pieces)
				{
					completeSets = Math.min(completeSets, heldByBase.getOrDefault(ItemVariationMapping.map(piece), 0));
				}
				int heldSets = unopened + (completeSets == Integer.MAX_VALUE ? 0 : completeSets);
				quantity = Math.min(tracked.totalBought(), heldSets);
				if (quantity <= 0)
				{
					continue;
				}
				int fromUnopened = Math.min(quantity, unopened);
				consume(heldByBase, ItemVariationMapping.map(itemId), fromUnopened);
				int fromPieces = quantity - fromUnopened;
				for (int piece : pieces)
				{
					consume(heldByBase, ItemVariationMapping.map(piece), fromPieces);
				}
			}
			else
			{
				int base = ItemVariationMapping.map(itemId);
				// The list only shows what you currently hold (bank + inventory + gear); items you
				// have none of drop off until they come back.
				quantity = Math.min(tracked.totalBought(), heldByBase.getOrDefault(base, 0));
				if (quantity <= 0)
				{
					continue;
				}
				consume(heldByBase, base, quantity);
			}

			PortfolioRow row = buildRow(itemManager, config, itemId, tracked, quantity);
			rows.add(row);
			total += row.getProfitTotal();
		}

		sort(rows, config.sortOrder());
		lastTotalProfit = total;
		return rows;
	}

	/**
	 * A cheap snapshot of the held quantities of just the tracked items (and set pieces), keyed by
	 * variation base. Used to decide whether an inventory change actually affected the panel, so we
	 * can skip a full rebuild when it did not. Does no pricing or row building.
	 */
	public Map<Integer, Integer> trackedHeldSignature(Map<Integer, Integer> liveQuantities)
	{
		if (data.getItems().isEmpty())
		{
			return new HashMap<>();
		}

		Set<Integer> relevant = new HashSet<>();
		for (Integer id : data.getItems().keySet())
		{
			relevant.add(ItemVariationMapping.map(id));
			int[] pieces = ItemSets.piecesFor(id);
			if (pieces != null)
			{
				for (int piece : pieces)
				{
					relevant.add(ItemVariationMapping.map(piece));
				}
			}
		}

		Map<Integer, Integer> held = new HashMap<>();
		for (Map.Entry<Integer, Integer> e : data.getBank().entrySet())
		{
			addHeld(held, e.getKey(), e.getValue());
		}
		if (liveQuantities != null)
		{
			for (Map.Entry<Integer, Integer> e : liveQuantities.entrySet())
			{
				addHeld(held, e.getKey(), e.getValue());
			}
		}

		Map<Integer, Integer> signature = new HashMap<>();
		for (Integer base : relevant)
		{
			int quantity = held.getOrDefault(base, 0);
			if (quantity != 0)
			{
				signature.put(base, quantity);
			}
		}
		return signature;
	}

	/** The most recent buy date across a tracked item's lots (0 if none). */
	private static long newestBuy(TrackedItem tracked)
	{
		long newest = 0;
		for (Lot lot : tracked.getLots())
		{
			if (lot.getEpochMs() > newest)
			{
				newest = lot.getEpochMs();
			}
		}
		return newest;
	}

	/** Removes up to {@code amount} of a base from the held pool. */
	private static void consume(Map<Integer, Integer> heldByBase, int base, int amount)
	{
		if (amount <= 0)
		{
			return;
		}
		int remaining = heldByBase.getOrDefault(base, 0) - amount;
		if (remaining > 0)
		{
			heldByBase.put(base, remaining);
		}
		else
		{
			heldByBase.remove(base);
		}
	}

	/** Builds one display row for {@code quantity} held units of a tracked item, valued LIFO. */
	private PortfolioRow buildRow(ItemManager itemManager, BankStonksConfig config, int itemId, TrackedItem tracked, int quantity)
	{
		LotValuation valuation = tracked.value(quantity);
		long avg = valuation.getAveragePrice();
		long rawCurrent = itemManager.getItemPrice(itemId);
		long effectiveCurrent = config.applyGeTax() ? netAfterTax(rawCurrent) : rawCurrent;
		long profitEach = effectiveCurrent - avg;
		long profitTotal = profitEach * quantity;

		List<Lot> lots = new ArrayList<>(tracked.getLots());
		lots.sort(Comparator.comparingLong(Lot::getEpochMs).reversed());

		String name = itemManager.getItemComposition(itemId).getName();
		return new PortfolioRow(itemId, name, quantity, avg, rawCurrent, profitEach, profitTotal, valuation.getHeldSinceEpochMs(), lots, false);
	}

	/** Builds a pinned row for a locked item, valued at its locked lot's price, date and quantity. */
	private PortfolioRow buildLockedRow(ItemManager itemManager, BankStonksConfig config, int itemId, TrackedItem tracked)
	{
		Lot locked = tracked.getLockedLot();
		int quantity = locked.getQuantity();
		long avg = locked.unitPrice();
		long rawCurrent = itemManager.getItemPrice(itemId);
		long effectiveCurrent = config.applyGeTax() ? netAfterTax(rawCurrent) : rawCurrent;
		long profitEach = effectiveCurrent - avg;
		long profitTotal = profitEach * quantity;

		// A locked item shows no history dropdown (empty lots); the underlying lots are still kept
		// and updated, and are restored when it is unlocked.
		String name = itemManager.getItemComposition(itemId).getName();
		return new PortfolioRow(itemId, name, quantity, avg, rawCurrent, profitEach, profitTotal, locked.getEpochMs(), new ArrayList<>(), true);
	}

	private static void sort(List<PortfolioRow> rows, SortOrder order)
	{
		final Comparator<PortfolioRow> comparator;
		switch (order)
		{
			case MOST_PROFIT:
				comparator = Comparator.comparingLong(PortfolioRow::getProfitTotal).reversed();
				break;
			case MOST_LOSS:
				comparator = Comparator.comparingLong(PortfolioRow::getProfitTotal);
				break;
			case HIGHEST_VALUE:
				comparator = Comparator.comparingLong((PortfolioRow r) -> r.getCurrentPrice() * r.getQuantity()).reversed();
				break;
			case NAME:
				comparator = Comparator.comparing(r -> r.getName().toLowerCase());
				break;
			case BIGGEST_MOVERS:
			default:
				comparator = Comparator.comparingLong((PortfolioRow r) -> Math.abs(r.getProfitTotal())).reversed();
				break;
		}
		rows.sort(comparator);
	}
}

package com.bankstonks;

import com.bankstonks.model.LotValuation;
import com.bankstonks.model.TrackedItem;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;

/**
 * Shows a tooltip when hovering a tracked item in the bank: how many are in your portfolio,
 * the average price you bought them for, and the current profit/loss on that amount.
 */
@Singleton
public class BankOverlay extends WidgetItemOverlay
{
	private final Client client;
	private final PortfolioManager manager;
	private final ItemManager itemManager;
	private final TooltipManager tooltipManager;
	private final BankStonksConfig config;

	@Inject
	public BankOverlay(Client client, PortfolioManager manager, ItemManager itemManager,
		TooltipManager tooltipManager, BankStonksConfig config)
	{
		this.client = client;
		this.manager = manager;
		this.itemManager = itemManager;
		this.tooltipManager = tooltipManager;
		this.config = config;
		showOnBank();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.bankOverlay() || !manager.hasAccount())
		{
			return;
		}

		// Resolve to the tracked (bought) item, matching charged/banked items back to the
		// uncharged item they were bought as.
		int boughtId = manager.boughtIdForBankItem(itemId);
		if (boughtId < 0)
		{
			return;
		}

		TrackedItem tracked = manager.getTracked(boughtId);
		if (tracked == null || tracked.totalBought() <= 0)
		{
			return;
		}

		if (PortfolioManager.isBlocked(config, itemManager.getItemComposition(boughtId).getName()))
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds == null)
		{
			return;
		}
		Point mouse = client.getMouseCanvasPosition();
		if (mouse == null || !bounds.contains(mouse.getX(), mouse.getY()))
		{
			return;
		}

		int quantity = Math.min(tracked.totalBought(), widgetItem.getQuantity());
		if (quantity <= 0)
		{
			return;
		}

		LotValuation valuation = tracked.value(quantity);
		long avg = valuation.getAveragePrice();
		long rawCurrent = itemManager.getItemPrice(boughtId);
		long current = config.applyGeTax() ? PortfolioManager.netAfterTax(rawCurrent) : rawCurrent;
		long profit = (current - avg) * quantity;

		java.awt.Color plColor = profit >= 0 ? config.profitColor() : config.lossColor();

		String heldAge = Format.age(valuation.getHeldSinceEpochMs());
		String heldLine = heldAge.isEmpty() ? "" : "Held: " + heldAge + "</br>";

		String text = quantity + " @ " + Format.plain(avg) + " ea</br>"
			+ heldLine
			+ "P/L: " + ColorUtil.wrapWithColorTag(Format.gp(profit), plColor);

		tooltipManager.add(new Tooltip(text));
	}
}

package com.bankstonks;

import com.bankstonks.model.PortfolioRow;
import com.bankstonks.ui.BankStonksPanel;
import com.bankstonks.ui.PortfolioActions;
import com.google.inject.Provides;
import java.awt.Color;
import java.awt.event.HierarchyEvent;
import java.awt.image.BufferedImage;
import java.time.temporal.ChronoUnit;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.task.Schedule;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.http.api.item.ItemPrice;

@Slf4j
@PluginDescriptor(
	name = "Bank Stonks",
	description = "Tracks GE buys and shows live profit/loss vs the wiki price for what you hold",
	tags = {"grand", "exchange", "ge", "profit", "loss", "portfolio", "stonks", "flip", "price", "bank"}
)
public class BankStonksPlugin extends Plugin implements PortfolioActions
{
	/** The bank interface widget group id. */
	private static final int BANK_GROUP_ID = 12;

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private ItemManager itemManager;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private BankStonksConfig config;
	@Inject
	private ConfigManager configManager;
	@Inject
	private PortfolioManager manager;
	@Inject
	private GrandExchangeBuyTracker buyTracker;
	@Inject
	private BankTracker bankTracker;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private BankOverlay bankOverlay;

	private BankStonksPanel panel;
	private NavigationButton navButton;

	/**
	 * Set by any event that could change the panel; the actual rebuild happens at most once per
	 * game tick and only while the sidebar is open. This coalesces the flood of inventory/bank
	 * changes during normal play into a single refresh, and skips work entirely when the panel is
	 * closed. (The bank overlay reads live data on render and is unaffected.)
	 */
	private volatile boolean refreshPending;

	/**
	 * When true the next rebuild is unconditional (something other than inventory changed: an edit,
	 * a config change, the price timer, opening the panel). Inventory changes leave this false, so
	 * they only rebuild when the tracked items' held quantities actually changed.
	 */
	private volatile boolean forceRebuild;

	/** The tracked items' held quantities at the last rebuild, to detect real changes. */
	private Map<Integer, Integer> lastHeldSignature = new HashMap<>();

	@Provides
	BankStonksConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankStonksConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		panel = new BankStonksPanel(itemManager, config, this);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/nav_button.png");
		navButton = NavigationButton.builder()
			.tooltip("Bank Stonks")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(bankOverlay);

		// Rebuild once whenever the sidebar becomes visible (e.g. the user opens the tab), so it
		// shows current data without us having to rebuild it while it was hidden.
		panel.addHierarchyListener(e ->
		{
			if ((e.getChangeFlags() & HierarchyEvent.SHOWING_CHANGED) != 0 && panel.isShowing())
			{
				requestForceRefresh();
			}
		});

		requestForceRefresh();
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(bankOverlay);
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGING_IN || state == GameState.HOPPING)
		{
			// The client is about to replay all existing GE offers; don't re-record them.
			buyTracker.setLoginSync(true);
		}
		if (state == GameState.LOGGED_IN)
		{
			// Load the account immediately (the bank overlay needs it), but leave the panel
			// rebuild to the coalesced tick handler.
			manager.setAccount(client.getAccountHash());
			requestForceRefresh();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// The login/hop offer replay all fires before the first tick, so the sync window is over.
		buyTracker.setLoginSync(false);

		// Coalesce all the refresh requests since the last tick, and only bother while the sidebar
		// is open. An inventory-only request rebuilds only if a tracked item's held quantity has
		// actually changed; edits / config / the price timer force it regardless.
		if (refreshPending && panel != null && panel.isShowing())
		{
			refreshPending = false;
			Map<Integer, Integer> signature = manager.trackedHeldSignature(liveHeldQuantities());
			if (forceRebuild || !signature.equals(lastHeldSignature))
			{
				forceRebuild = false;
				lastHeldSignature = signature;
				refresh();
			}
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		// The bank opening can change what counts as held; queue a refresh.
		if (event.getGroupId() == BANK_GROUP_ID)
		{
			requestForceRefresh();
		}
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		if (buyTracker.handle(event))
		{
			requestForceRefresh();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		boolean bankChanged = bankTracker.handle(event);
		int id = event.getContainerId();
		if (bankChanged || id == InventoryID.INV || id == InventoryID.WORN)
		{
			requestRefresh();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Only react to actual setting changes. Our own portfolio saves land in the same config
		// group under the data_ key; those must not force a rebuild or every bank change and GE buy
		// (which call save()) would rebuild the whole panel.
		if (BankStonksConfig.GROUP.equals(event.getGroup()) && !event.getKey().startsWith(PortfolioManager.DATA_KEY_PREFIX))
		{
			requestForceRefresh();
		}
	}

	@Schedule(period = 5, unit = ChronoUnit.MINUTES)
	public void scheduledRefresh()
	{
		// Picks up price changes while the panel sits open with nothing else happening.
		requestForceRefresh();
	}

	/**
	 * Marks the panel as needing a rebuild from an inventory change; the tick only rebuilds if a
	 * tracked item's held quantity actually changed.
	 */
	private void requestRefresh()
	{
		refreshPending = true;
	}

	/** Requests an unconditional rebuild (used for edits, config, prices, opening the panel). */
	private void requestForceRefresh()
	{
		forceRebuild = true;
		refreshPending = true;
	}

	private void refresh()
	{
		if (panel == null)
		{
			return;
		}
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				manager.setAccount(client.getAccountHash());
			}

			if (!manager.hasAccount())
			{
				panel.update(Collections.emptyList(), 0L);
				return;
			}

			List<PortfolioRow> rows = manager.buildRows(itemManager, config, liveHeldQuantities());
			panel.update(rows, manager.getLastTotalProfit());
		});
	}

	/**
	 * Live item quantities from the inventory, worn equipment and the Dizana's quiver (client
	 * thread). The quiver holds equipped ammunition in its own container, separate from the worn
	 * slots, so it must be counted too or quivered ammo would drop out of the list.
	 */
	private Map<Integer, Integer> liveHeldQuantities()
	{
		Map<Integer, Integer> out = new HashMap<>();
		addContainer(out, InventoryID.INV);
		addContainer(out, InventoryID.WORN);
		addQuiver(out);
		return out;
	}

	/**
	 * Adds the ammunition stored in a Dizana's quiver. The quiver keeps its ammo in varplayers
	 * rather than an item container, so it is not covered by {@link #addContainer}.
	 */
	private void addQuiver(Map<Integer, Integer> out)
	{
		int ammoId = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
		int ammoQty = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT);
		if (ammoId > 0 && ammoQty > 0)
		{
			out.merge(itemManager.canonicalize(ammoId), ammoQty, Integer::sum);
		}
	}

	private void addContainer(Map<Integer, Integer> out, int containerId)
	{
		ItemContainer container = client.getItemContainer(containerId);
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			// Canonicalize so a noted (or placeholder) item counts as the real item it was bought as.
			out.merge(itemManager.canonicalize(item.getId()), item.getQuantity(), Integer::sum);
		}
	}

	// ---- PortfolioActions (invoked from the panel on the EDT) ----------------

	@Override
	public void addManual(String query, int quantity, long priceEach, long heldSinceEpochMs)
	{
		clientThread.invokeLater(() ->
		{
			if (!manager.hasAccount())
			{
				panel.setStatus("Log in first.", Color.GRAY);
				return;
			}

			int itemId = resolveItemId(query);
			if (itemId <= 0)
			{
				panel.setStatus("No item found for \"" + query + "\".", Color.RED);
				return;
			}

			String name = itemManager.getItemComposition(itemId).getName();
			// Adding an item you want tracked implicitly unblocks it.
			configManager.setConfiguration(BankStonksConfig.GROUP, BankStonksConfig.KEY_BLOCK_LIST, BlockLists.remove(config.blockList(), name));
			manager.recordBuy(itemId, quantity, priceEach * quantity, heldSinceEpochMs);
			manager.save();
			panel.setStatus("Added " + quantity + " x " + name + ".", Color.LIGHT_GRAY);
			panel.clearManualEntry();
			refresh();
		});
	}

	@Override
	public void untrackItem(int itemId)
	{
		clientThread.invokeLater(() ->
		{
			manager.removeItem(itemId);
			manager.save();
			refresh();
		});
	}

	@Override
	public void untrackLot(int itemId, int quantity, long spent, long epochMs)
	{
		clientThread.invokeLater(() ->
		{
			manager.removeLot(itemId, quantity, spent, epochMs);
			manager.save();
			refresh();
		});
	}

	@Override
	public void blockItem(String itemName)
	{
		configManager.setConfiguration(BankStonksConfig.GROUP, BankStonksConfig.KEY_BLOCK_LIST, BlockLists.add(config.blockList(), itemName));
		refresh();
	}

	@Override
	public void lockItem(int itemId)
	{
		clientThread.invokeLater(() ->
		{
			manager.lockItem(itemId);
			manager.save();
			refresh();
		});
	}

	@Override
	public void lockLot(int itemId, int quantity, long spent, long epochMs)
	{
		clientThread.invokeLater(() ->
		{
			manager.lockLot(itemId, quantity, spent, epochMs);
			manager.save();
			refresh();
		});
	}

	@Override
	public void unlockItem(int itemId)
	{
		clientThread.invokeLater(() ->
		{
			manager.unlockItem(itemId);
			manager.save();
			refresh();
		});
	}

	/** Resolves a user-typed name to an item id, preferring an exact (case-insensitive) match. */
	private int resolveItemId(String query)
	{
		List<ItemPrice> results = itemManager.search(query);
		if (results == null || results.isEmpty())
		{
			return -1;
		}
		for (ItemPrice result : results)
		{
			if (result.getName().equalsIgnoreCase(query))
			{
				return result.getId();
			}
		}
		return results.get(0).getId();
	}
}
